/**
 * Cloudflare Observability Demo
 *
 * Workers Observability (自動 trace) + AI Gateway (LLM span) を
 * Honeycomb にエクスポートするデモ Worker。
 *
 * --- セットアップ手順 ---
 * 1. AI Gateway を Dashboard で作成し、ACCOUNT_ID / GATEWAY_ID を控える
 * 2. wrangler secret put HONEYCOMB_API_KEY で Honeycomb の API キーを登録
 * 3. wrangler deploy
 * 4. Dashboard → Workers → observability-demo → Observability → Destinations で
 *    OTLP exporter を追加:
 *      Endpoint: https://api.honeycomb.io/v1/traces
 *      Header:   x-honeycomb-team: <HONEYCOMB_API_KEY>
 * 5. AI Gateway → Settings → OTel exporter を追加 (同じ Honeycomb endpoint)
 * 6. curl https://observability-demo.<subdomain>.workers.dev/ask?q=hello
 */

interface Env {
  AI: Ai;
  ACCOUNT_ID: string;
  GATEWAY_ID: string;
}

// --- Trace ID / Span ID 生成ユーティリティ ---

/** 32 文字の hex trace ID を生成 */
function generateTraceId(): string {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/** 16 文字の hex span ID を生成 */
function generateSpanId(): string {
  const bytes = new Uint8Array(8);
  crypto.getRandomValues(bytes);
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    // --- GET / --- ヘルスチェック
    if (url.pathname === "/") {
      return Response.json({ status: "ok", service: "observability-demo" });
    }

    // --- GET /ask?q=<prompt> --- AI Gateway 経由で LLM を呼ぶ
    if (url.pathname === "/ask") {
      const prompt = url.searchParams.get("q") || "What is Cloudflare?";

      // 自前の trace context を生成 (Workers 自動計装の trace ID は取得不可)
      const traceId = generateTraceId();
      const spanId = generateSpanId();

      // Workers Logs に trace ID を出力 → Honeycomb で検索可能にする
      console.log(
        JSON.stringify({
          msg: "ai_gateway_call",
          traceId,
          spanId,
          prompt,
        }),
      );

      // --- 方法 A: AI Binding 経由 (シンプル) ---
      // Workers AI Binding は AI Gateway の OTel trace context ヘッダを渡せないため、
      // Gateway 経由の trace 連携には HTTP 直接呼び出しを使う。
      //
      // env.AI.run() は内部的に AI Gateway を経由させることもできるが、
      // cf-aig-otel-* ヘッダを付与する手段がないため、trace 統合デモには不向き。

      // --- 方法 B: AI Gateway HTTP 直接呼び出し (trace 連携あり) ---
      const gatewayUrl = `https://gateway.ai.cloudflare.com/v1/${env.ACCOUNT_ID}/${env.GATEWAY_ID}/workers-ai/@cf/meta/llama-3.3-70b-instruct-fp8-fast`;

      const aiResponse = await fetch(gatewayUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          // AI Gateway に trace context を伝播
          "cf-aig-otel-trace-id": traceId,
          "cf-aig-otel-parent-span-id": spanId,
          // カスタムメタデータ (Honeycomb の span 属性に付与される)
          "cf-aig-metadata": JSON.stringify({
            user: "demo",
            endpoint: "/ask",
          }),
        },
        body: JSON.stringify({
          messages: [{ role: "user", content: prompt }],
          max_tokens: 256,
        }),
      });

      const result = await aiResponse.json();

      return Response.json({
        traceId,
        prompt,
        result,
      });
    }

    // --- GET /simple --- AI Binding 経由 (trace 連携なし、自動計装のみ)
    if (url.pathname === "/simple") {
      const prompt =
        url.searchParams.get("q") || "Say hello in one sentence.";

      const result = await env.AI.run(
        "@cf/meta/llama-3.3-70b-instruct-fp8-fast",
        {
          messages: [{ role: "user", content: prompt }],
          max_tokens: 128,
        },
      );

      return Response.json({ prompt, result });
    }

    return Response.json({ error: "Not found" }, { status: 404 });
  },
};

