/**
 * Cloudflare Observability Demo
 *
 * Workers Observability + AI Gateway + R2 + D1 + Queue + Workflow を
 * Honeycomb にエクスポートするデモ Worker。
 */

import { WorkflowEntrypoint, WorkflowEvent, WorkflowStep } from "cloudflare:workers";

// ---------- Types ----------

interface Env {
  AI: Ai;
  BUCKET: R2Bucket;
  DB: D1Database;
  QUEUE: Queue;
  INGEST_WORKFLOW: Workflow;
  ACCOUNT_ID: string;
  GATEWAY_ID: string;
}

interface AiTextResponse {
  response?: string;
  usage?: { prompt_tokens?: number; completion_tokens?: number };
}

interface QueueMessage {
  type: "ai_response";
  prompt: string;
  response: string;
  traceId: string;
  ts: string;
}

// ---------- Trace helpers ----------

function generateTraceId(): string {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

function generateSpanId(): string {
  const bytes = new Uint8Array(8);
  crypto.getRandomValues(bytes);
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

// ---------- Workflow ----------

export class IngestWorkflow extends WorkflowEntrypoint<Env> {
  async run(event: WorkflowEvent<{ prompt: string }>, step: WorkflowStep) {
    const { prompt } = event.payload;

    // Step 1: AI で応答を生成
    const aiResult = await step.do("generate response", async () => {
      const res = (await this.env.AI.run("@cf/meta/llama-3.3-70b-instruct-fp8-fast", {
        messages: [{ role: "user", content: prompt }],
        max_tokens: 256,
      })) as AiTextResponse;
      return { response: res.response ?? "", usage: res.usage };
    });

    // Step 2: R2 に保存
    const r2Key = await step.do("save to r2", async () => {
      const key = `workflow/${Date.now()}.json`;
      await this.env.BUCKET.put(
        key,
        JSON.stringify({ prompt, response: aiResult.response, ts: new Date().toISOString() }),
      );
      return key;
    });

    // Step 3: D1 にログを記録
    await step.do("log to d1", async () => {
      await this.env.DB.prepare(
        "INSERT INTO query_logs (prompt, model, tokens_in, tokens_out, r2_key) VALUES (?, ?, ?, ?, ?)",
      )
        .bind(
          prompt,
          "@cf/meta/llama-3.3-70b-instruct-fp8-fast",
          aiResult.usage?.prompt_tokens ?? null,
          aiResult.usage?.completion_tokens ?? null,
          r2Key,
        )
        .run();
    });

    return { r2Key, response: aiResult.response };
  }
}

// ---------- Router ----------

export default {
  // ---- HTTP ----
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    // GET / — ヘルスチェック
    if (url.pathname === "/") {
      return Response.json({ status: "ok", service: "observability-demo" });
    }

    // GET /ask?q=<prompt>
    // AI Gateway HTTP → R2 保存 → D1 ログ → Queue に送信
    if (url.pathname === "/ask") {
      const prompt = url.searchParams.get("q") || "What is Cloudflare?";
      const traceId = generateTraceId();
      const spanId = generateSpanId();

      console.log(JSON.stringify({ msg: "ai_gateway_call", traceId, spanId, prompt }));

      const gatewayUrl = `https://gateway.ai.cloudflare.com/v1/${env.ACCOUNT_ID}/${env.GATEWAY_ID}/workers-ai/@cf/meta/llama-3.3-70b-instruct-fp8-fast`;

      const aiResponse = await fetch(gatewayUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "cf-aig-otel-trace-id": traceId,
          "cf-aig-otel-parent-span-id": spanId,
          "cf-aig-metadata": JSON.stringify({ user: "demo", endpoint: "/ask" }),
        },
        body: JSON.stringify({
          messages: [{ role: "user", content: prompt }],
          max_tokens: 256,
        }),
      });

      const result = (await aiResponse.json()) as AiTextResponse;
      const responseText = result.response ?? "";

      // R2 に保存
      const r2Key = `ask/${Date.now()}.json`;
      await env.BUCKET.put(
        r2Key,
        JSON.stringify({ prompt, response: responseText, traceId, ts: new Date().toISOString() }),
      );

      // D1 にログ
      await env.DB.prepare(
        "INSERT INTO query_logs (prompt, model, tokens_in, tokens_out, r2_key, trace_id) VALUES (?, ?, ?, ?, ?, ?)",
      )
        .bind(
          prompt,
          "@cf/meta/llama-3.3-70b-instruct-fp8-fast",
          result.usage?.prompt_tokens ?? null,
          result.usage?.completion_tokens ?? null,
          r2Key,
          traceId,
        )
        .run();

      // Queue に送信
      await env.QUEUE.send({
        type: "ai_response",
        prompt,
        response: responseText,
        traceId,
        ts: new Date().toISOString(),
      } satisfies QueueMessage);

      return Response.json({ traceId, prompt, response: responseText, r2Key });
    }

    // GET /simple?q=<prompt> — AI Binding 経由 (自動計装のみ)
    if (url.pathname === "/simple") {
      const prompt = url.searchParams.get("q") || "Say hello in one sentence.";

      const result = (await env.AI.run("@cf/meta/llama-3.3-70b-instruct-fp8-fast", {
        messages: [{ role: "user", content: prompt }],
        max_tokens: 128,
      })) as AiTextResponse;

      return Response.json({ prompt, result });
    }

    // GET /r2 — オブジェクト一覧
    if (url.pathname === "/r2") {
      const listed = await env.BUCKET.list({ limit: 50 });
      const objects = listed.objects.map((o) => ({
        key: o.key,
        size: o.size,
        uploaded: o.uploaded.toISOString(),
      }));
      return Response.json({ objects });
    }

    // GET /r2/* — オブジェクト取得
    if (url.pathname.startsWith("/r2/")) {
      const key = url.pathname.slice(4);
      const object = await env.BUCKET.get(key);
      if (!object) return Response.json({ error: "Not found" }, { status: 404 });
      return new Response(await object.text(), {
        headers: { "Content-Type": "application/json" },
      });
    }

    // GET /logs — D1 クエリログ
    if (url.pathname === "/logs") {
      const limit = Number(url.searchParams.get("limit")) || 20;
      const { results } = await env.DB.prepare(
        "SELECT * FROM query_logs ORDER BY created_at DESC LIMIT ?",
      )
        .bind(limit)
        .all();
      return Response.json({ logs: results });
    }

    // POST /workflow?q=<prompt> — Workflow を起動
    if (url.pathname === "/workflow" && request.method === "POST") {
      const prompt = url.searchParams.get("q") || "Summarize Cloudflare Workers in one sentence.";
      const id = crypto.randomUUID();
      const instance = await env.INGEST_WORKFLOW.create({ id, params: { prompt } });
      return Response.json({ instanceId: instance.id, prompt });
    }

    // GET /workflow/:id — Workflow の状態
    if (url.pathname.startsWith("/workflow/")) {
      const id = url.pathname.slice(10);
      const instance = await env.INGEST_WORKFLOW.get(id);
      const status = await instance.status();
      return Response.json({ instanceId: id, status });
    }

    return Response.json({ error: "Not found" }, { status: 404 });
  },

  // ---- Queue Consumer ----
  async queue(batch: MessageBatch<QueueMessage>, env: Env): Promise<void> {
    for (const msg of batch.messages) {
      const { type, prompt, response, traceId, ts } = msg.body;

      console.log(
        JSON.stringify({
          msg: "queue_consume",
          type,
          traceId,
          promptLength: prompt.length,
          responseLength: response.length,
          ts,
        }),
      );

      // Queue Consumer: R2 にアーカイブ保存
      const archiveKey = `archive/${traceId}.json`;
      await env.BUCKET.put(archiveKey, JSON.stringify(msg.body));

      msg.ack();
    }
  },
};

