import { Stack } from "alchemy";
import * as Cloudflare from "alchemy/Cloudflare";
import * as Effect from "effect/Effect";

export default Stack(
  "observability-demo",
  {
    providers: Cloudflare.providers(),
    state: Cloudflare.state(),
  },
  Effect.gen(function* () {
    // --- R2 Bucket ---
    const bucket = yield* Cloudflare.R2Bucket("obs-demo");

    // --- D1 Database ---
    const db = yield* Cloudflare.D1Database("obs-demo", {
      migrationsDir: "./migrations",
    });

    // --- Queue ---
    const queue = yield* Cloudflare.Queue("obs-demo-queue");

    // --- AI Gateway ---
    const aiGateway = yield* Cloudflare.AiGateway("obs-demo-gateway", {
      collectLogs: true,
      cacheTtl: null,
    });

    // --- Worker ---
    const worker = yield* Cloudflare.Worker("observability-demo", {
      main: "./src/index.ts",
      compatibility: {
        date: "2025-05-01",
      },
      observability: {
        enabled: true,
        head_sampling_rate: 1,
      },
      bindings: {
        BUCKET: bucket,
        DB: db,
        QUEUE: queue,
        AI_GATEWAY: aiGateway,
      },
    });

    // --- Queue Consumer ---
    yield* Cloudflare.QueueConsumer("obs-demo-consumer", {
      queueId: queue.queueId,
      scriptName: worker.workerName,
      settings: {
        batchSize: 10,
        maxRetries: 3,
        maxWaitTimeMs: 5000,
      },
    });

    return { worker, bucket, db, queue, aiGateway };
  }),
);

